function createFrontlineGuidedControl({group,resolve,targets,reason,activate,pod,podTrack,capture,cancel,nose}) {
  let life=null,enabled=false,accepted=null,lastAir=null,lastReleaseStamp=null,cancelledRadioShot=null;
  const manual=[0,0];
  const key=r=>r&&[r.battle,r.unit,r.life].every(v=>Number.isSafeInteger(v)&&v>=0)?`${r.battle}:${r.unit}:${r.life}`:null;
  const modes=new Set(['ir','sarh','arh','aim54','tv','iir','laser','beam','radio','arm']);
  const guided=d=>!!d&&modes.has(d.guidance);
  function target(value,unit){
    const known=resolve(value),ref=known?.unitRef;
    return key(ref)&&ref.battle===unit.unit.battle?{battle:ref.battle,unit:ref.unit,life:ref.life}:null;
  }
  function clear(){
    if(lastAir?.ctl?.radio?.native){lastAir.ctl.radio=null;lastAir.ctl.holdAim=null;}
    life=null;enabled=false;accepted=null;lastAir=null;lastReleaseStamp=null;cancelledRadioShot=null;manual[0]=manual[1]=0;
  }
  function bind(air,unit){
    const next=key(unit?.unit);if(!next)return false;
    if(life!==next){clear();life=next;enabled=unit.seeker?.enabled===true;}
    lastAir=air;return true;
  }
  function selectionMatches(air,unit){
    const control=unit?.weapon_control,g=group(air);
    // A changed selected source must wait for its accepted control echo.
    return !!g&&control?.store_id===g.id&&control?.store_index==null;
  }
  function project(air,unit){
    const host=unit?.seeker,sk=air?.ctl?.seeker;
    if(!host||!sk)return;
    const d=group(air)?.def,definition=guided(d)?d:null,matched=!!definition&&selectionMatches(air,unit);
    if(sk.def!==definition)Object.assign(sk,{def:definition,state:'off',t:0,target:null,cand:null,est:null,point:null,cue:null,slew:null,look:null,dir:nose(air.plane)});
    const hostStatus=['off','prep','search','capturing','track','ready'].includes(host.status)?host.status:'off';
    const status=matched?hostStatus:definition&&enabled?'prep':'off';
    sk.state=status;sk.t=matched&&Number.isFinite(host.progress_s)?Math.max(0,host.progress_s):0;
    sk.target=matched&&host.target?resolve(host.target):null;sk.cand=status==='capturing'?sk.target:null;
    const why=matched?host.reason||null:definition?'等待服务器确认所选武器':null;
    sk.nativeStatus=status;sk.nativeProgress=sk.t;sk.nativeReason=why;sk.why=why;
  }
  function accept(air,unit,missiles=[]){
    if(!bind(air,unit))return;
    accepted=unit.seeker||null;project(air,unit);
    const radio=missiles.find(row=>row.shooter===unit.unit.unit&&row.phase==='radio'&&row.shot_id!==cancelledRadioShot);
    const ctl=air.ctl;
    if(ctl&&radio){
      if(!ctl.radio?.native||ctl.radio.shot_id!==radio.shot_id){manual[0]=manual[1]=0;ctl.radio={native:true,shot_id:radio.shot_id,guide:{phase:'radio',cmd:[0,0]}};ctl.holdAim=nose(air.plane);}
    }else if(ctl?.radio?.native){ctl.radio=null;ctl.holdAim=null;manual[0]=manual[1]=0;}
  }
  function intent(air,unit){
    if(!bind(air,unit))return null;
    const ctl=air.ctl||{},sk=ctl.seeker||{},rd=ctl.radar,p=ctl.pod,d=group(air)?.def;
    const laser=!!p?.cfg&&(p.cfg.laser===true||p.cfg.beam===true)&&['acq','track','memory','point'].includes(p.state);
    let requested;
    if(['sarh','arh','aim54'].includes(d?.guidance))requested=rd?.stt?.target||ctl.selected;
    else if(['laser','beam'].includes(d?.guidance))requested=p?.target||sk.target||sk.cand||ctl.selected;
    else requested=sk.target||sk.cand||p?.target||ctl.selected;
    // A spent station can still illuminate an already airborne native missile.
    if(!guided(d))requested=rd?.stt?.target||p?.target||requested||accepted?.requested;
    return {enabled,radar:rd?.on===true,target:target(requested,unit),laser,
      ecm:air.ecmOff!==true&&!!air.stores?.items.some(it=>!it.gone&&(it.def?.kind==='ecm'||it.def?.jam)),manual:manual.slice()};
  }
  function action(air,unit,name,stamp){
    if(!bind(air,unit))return undefined;
    const ctl=air.ctl||{},sk=ctl.seeker||{},g=group(air),d=g?.def;
    if(name==='seekerOff'||name==='cancel'){
      if(name==='cancel'&&ctl.radio?.native)cancelledRadioShot=ctl.radio.shot_id;
      enabled=false;manual[0]=manual[1]=0;
      if(name==='cancel')cancel(air);else{sk.state='off';sk.target=sk.cand=null;}
      return true;
    }
    if(name==='targetNext'&&d?.guidance==='arm'){
      const list=targets().filter(t=>target(t,unit));if(!list.length)return reason(air,'没有当前可见的原生目标');
      ctl.selected=list[(list.indexOf(ctl.selected)+1)%list.length];return true;
    }
    if(!guided(d))return undefined;
    if(name==='fire'){
      // The input bit requests release. Never call launchGuided/releaseStore here.
      if(stamp!=null&&stamp===lastReleaseStamp)return false;lastReleaseStamp=stamp??null;
      air.storeTap=true;return true;
    }
    if(name==='seekerPower'){
      enabled=!enabled;if(enabled){activate(air);sk.def=d;}else{sk.state='off';sk.target=sk.cand=null;}
      return true;
    }
    if(name!=='space')return undefined;
    const p=pod(air);
    if(d.kind!=='aam'&&p&&p.state==='free'&&ctl.sensor!=='seeker'){
      enabled=true;sk.def=d;return podTrack(air);
    }
    if(!enabled){enabled=true;activate(air);sk.def=d;return true;}
    if(d.kind==='aam'&&selectionMatches(air,unit)&&['track','ready'].includes(accepted?.status)){
      if(stamp!=null&&stamp===lastReleaseStamp)return false;lastReleaseStamp=stamp??null;air.storeTap=true;return true;
    }
    if(!['arm','radio','laser','beam'].includes(d.guidance)&&d.kind!=='aam'&&sk.state==='search')return capture(air);
    return reason(air,accepted?.reason||(['track','ready'].includes(accepted?.status)?'原生导引已就绪：使用原发射键投放':'等待服务器导引头准备或捕获'));
  }
  function radioSteer(air,dx,dy,dt=1/60){
    if(!air?.ctl?.radio?.native||!Number.isFinite(dx)||!Number.isFinite(dy)||!Number.isFinite(dt))return false;
    const ease=Math.exp(-Math.max(0,Math.min(.25,dt))*.8);
    manual[0]=Math.max(-1,Math.min(1,manual[0]*ease-dy*.004));
    manual[1]=Math.max(-1,Math.min(1,manual[1]*ease+dx*.004));
    const cmd=air.ctl.radio.guide.cmd;cmd[0]=manual[1];cmd[1]=manual[0];return true;
  }
  function neutral(air){manual[0]=manual[1]=0;if(air?.ctl?.radio?.native)air.ctl.radio.guide.cmd[0]=air.ctl.radio.guide.cmd[1]=0;}
  return {accept,project,intent,action,radioSteer,neutral,clear};
}

function launchCheck(air) {
      const ctl = airCtl(air), g = storeGroup(air.stores), d = g?.def, sk = ctl.seeker, P = air.plane, rd = ctl.radar, now = G4.time;
      if (!d) return { ok: false, reason: L10N("沒有選擇武器", "no weapon selected") };
      if (!g.items.length) return { ok: false, reason: L10N("掛架無彈", "no rounds on the stations") };
      if (P.crashed || P.damage.pilotDead) return { ok: false, reason: L10N("無法操作", "cannot operate") };
      if (now < ctl.nextLaunch) return { ok: false, reason: L10N("發射間隔中", "launch interval") };
      if (G4.online && d.kind !== "aam") return { ok: false, reason: L10N("線上暫不支援對地武器（下一階段）", "air-to-ground stores are not online yet") };
      if (!(d.kind === "aam" || d.kind === "agm")) return { ok: true, unguided: true };
      if (sk.def !== d || sk.state === "off") return { ok: false, reason: L10N("導引頭未啟動（按空白鍵）", "seeker off (Space)") };
      if (sk.state === "prep") return { ok: false, reason: L10N("導引頭準備中", "seeker preparing") };
      const from = P.worldPoint(g.items[0].p), scfg = seekerOf(d);
      if (WEAPON_STATUS[g.id]?.compat === "unverified_disabled") return { ok: false, reason: L10N("目前站位不相容（未查證）", "station not compatible (unverified)") };
      if (scfg.needs === "phoenix" && !rd?.R.phoenix) return { ok: false, reason: L10N("所需設備未安裝（AWG-9 類雷達）", "required equipment not fitted (an AWG-9 class radar)") };
      if (d.guidance === "arm") {
        // anti-radiation: an emitter the aircraft's receiver observes, chosen on the ARM page (J)
        if (!ctl.eq.rwr) return { ok: false, reason: L10N("所需設備未安裝（雷達警告接收機）", "required equipment not fitted (a radar warning receiver)") };
        const obs = air.armObs?.get(ctl.armSel);
        if (!obs) return { ok: false, reason: air.armObs?.size ? L10N("沒有選定輻射源（J 選擇）", "no emitter selected (J)") : L10N("沒有觀測到輻射源", "no emitter observed") };
        const age = now - obs.seen;
        if (age > (scfg.arm?.stale ?? 3)) return { ok: false, reason: `${L10N("目標資料過期", "target data stale")}（${age.toFixed(1)} s）` };
        const l = sub(obs.pos, from), dist = Math.hypot(...l);
        if (angleOf(noseOf(P), l) > d.gimbal * D2R) return { ok: false, reason: L10N("輻射源超出導引頭轉動範圍", "emitter beyond the seeker's limits") };
        if (dist > d.lockRange) return { ok: false, reason: L10N("目標超出射程", "target beyond range") };
        if (dist < (d.minRange || 0)) return { ok: false, reason: L10N("距離太近", "too close") };
        return { ok: true, arm: obs };
      }
      if (d.guidance === "beam") {
        // laser beam riding: the sight must hold the target (the beam from it), the nose roughly on it
        const pod = airPod(air);
        if (!pod?.cfg.beam) return { ok: false, reason: L10N("所需設備未安裝（駕束瞄準系統）", "required equipment not fitted (a beam-riding sight)") };
        if (!(pod.state === "track" || pod.state === "point")) return { ok: false, reason: L10N("缺少相應感測器支持（瞄準系統未追蹤：空白鍵）", "no sensor support (the sight is not tracking: Space)") };
        const at = pod.state === "point" ? pod.point : pod.est.p, l = sub(at, from), dist = Math.hypot(...l);
        if (angleOf(noseOf(P), l) > 15 * D2R) return { ok: false, reason: L10N("目標偏離機頭過大（駕束要大致對準）", "target too far off the nose for the beam") };
        if (dist > d.lockRange) return { ok: false, reason: L10N("目標超出射程", "target beyond range") };
        if (dist < (d.minRange || 0)) return { ok: false, reason: L10N("距離太近", "too close") };
        if (!airLos(P.worldPoint(pod.mount), at)) return { ok: false, reason: L10N("視線被遮擋", "line of sight blocked") };
        return { ok: true };
      }
      if (d.guidance === "radio") {
        // radio command: the pilot steers it; one under control at a time
        if (ctl.radio && airOrdnance.includes(ctl.radio)) return { ok: false, reason: L10N("已有一枚指令飛彈在操控中", "a command missile is already under control") };
        return { ok: true };
      }
      if (d.guidance === "laser") {
        // semi-active laser: the aircraft's own designator must hold a spot the seeker can see
        const spot = laserSpot(air);
        if (!airPod(air)?.cfg.laser) return { ok: false, reason: L10N("需要雷射指示器（這架飛機沒有）", "needs a laser designator (none fitted)") };
        if (!spot) return { ok: false, reason: L10N("沒有雷射照射點（空白鍵：Klen-PS 追蹤或地面點）", "no laser spot (Space: Klen-PS track or point)") };
        const l = sub(spot, from), dist = Math.hypot(...l);
        if (angleOf(noseOf(P), l) > d.gimbal * D2R) return { ok: false, reason: L10N("雷射點超出導引頭轉動範圍", "spot beyond the seeker's limits") };
        if (dist > d.lockRange) return { ok: false, reason: L10N("目標超出射程", "target beyond range") };
        if (d.minRange && dist < d.minRange) return { ok: false, reason: L10N("距離太近", "too close") };
        return { ok: true };
      }
      if (d.guidance === "ir" || imagingSeeker(d)) {
        if (sk.state !== "track" && d.guidance === "ir" && scfg.loal) {
          // lock after launch: the radar's track or the helmet sight's line given to it (where both allow)
          const tws = rd?.on && twsTrack(rd, ctl.selected);
          const des = rd?.on && rd.stt?.state === "track" && scfg.radarCue ? { target: rd.stt.target, est: rd.stt.est } : tws && scfg.radarCue ? { target: ctl.selected, est: tws } : ctl.eq.hms && scfg.hms && !ctl.sensor ? { dir: norm(P.aim) } : null;
          if (des) return { ok: true, loal: des };
          return { ok: false, reason: L10N("未捕獲目標（發射後鎖定需要雷達航跡或頭盔指向）", "no target captured (lock after launch needs a radar track or the helmet sight)") };
        }
        if (sk.state !== "track") return { ok: false, reason: sk.state === "memory" ? L10N("導引頭重新捕獲中", "seeker reacquiring") : sk.limited ? L10N("目標超出感測器轉動範圍", "target beyond the seeker's limits") : sk.why || L10N("未捕獲目標", "no target captured") };
        const dist = Math.hypot(...sub(sk.est.p, from));
        if (d.minRange && dist < d.minRange) return { ok: false, reason: L10N("距離太近", "too close") };
        return { ok: true };
      }
      // radar-guided: the aircraft's radar must hold the target (an active missile may go on a fresh track)
      if (!rd) return { ok: false, reason: L10N("缺少雷達支持（這架飛機沒有雷達）", "no radar support (no radar)") };
      if (!rd.on) return { ok: false, reason: L10N("缺少雷達支持（雷達關閉）", "no radar support (radar off)") };
      if (!rd.stt && (d.guidance === "arh" || d.guidance === "aim54") && twsTrack(rd, ctl.selected)) {
        const l = sub(twsTrack(rd, ctl.selected).p, from), dist = Math.hypot(...l);
        if (angleOf(noseOf(P), l) > d.gimbal * D2R) return { ok: false, reason: L10N("目標超出感測器轉動範圍", "target beyond the missile's limits") };
        if (dist > d.lockRange * 1.2) return { ok: false, reason: L10N("目標超出射程", "target beyond range") };
        if (d.minRange && dist < d.minRange) return { ok: false, reason: L10N("距離太近", "too close") };
        return { ok: true, tws: true };
      }
      if (!rd.stt) return { ok: false, reason: rd.mode === "tws" ? d.guidance === "arh" || d.guidance === "aim54" ? L10N("TWS 沒有選定航跡（按 R）", "no TWS target (R)") : L10N("半主動飛彈需要單目標鎖定（切換搜索模式後按 R）", "a semi-active missile needs a single-target lock") : L10N("缺少雷達支持（未鎖定，按 R）", "no radar support (no lock, R)") };
      if (rd.stt.state === "acq") return { ok: false, reason: L10N("雷達鎖定中", "radar locking") };
      if (rd.stt.state === "memory" && d.guidance === "sarh") return { ok: false, reason: L10N("目標資料已過期（雷達記憶中）", "target data stale (radar memory)") };
      if (now - rd.stt.seen > 1) return { ok: false, reason: L10N("目標資料已過期", "target data stale") };
      const l = sub(rd.stt.est.p, from), dist = Math.hypot(...l);
      if (angleOf(noseOf(P), l) > d.gimbal * D2R) return { ok: false, reason: L10N("目標超出感測器轉動範圍", "target beyond the missile's limits") };
      if (dist > d.lockRange * 1.2) return { ok: false, reason: L10N("目標超出射程", "target beyond range") };
      if (d.minRange && dist < d.minRange) return { ok: false, reason: L10N("距離太近", "too close") };
      return { ok: true };
    }
